-- exec-once = gsettings set org.gnome.desktop.interface cursor-size 24

-- Location provider
-- Night light: hyprsunset replaces gammastep (Hyprland 0.45+ removed wlr-gamma-control)
-- Starts with --temperature 4000 for warm filter at boot.
-- Interactive changes: hyprctl hyprsunset temperature <K>  |  hyprctl hyprsunset identity
-- Alternative: systemctl --user enable --now hyprsunset.service (then hyprsunset not needed in execs)

-- Forward bluetooth media commands to MPRIS

-- Resize and move windows based on matches (e.g. pip)

-- Waybar (lightweight bar for workspaces, tray, clock — v0.15+ has built-in SNI watcher)
-- NOTE: snixembed removed — Waybar 0.15+ handles StatusNotifierItems natively
-- Only re-add snixembed if you use XEmbed-only apps that don't support SNI

-- Start shell (caelestia — kept for OSD, launcher, lock screen)

-- 20-20-20 eye break + 30-5 walk break daemon (waybar custom/health toggles both)

-- Prayer times daemon: notifications and screen lock at prayer time

hl.on("hyprland.start", function()
    hl.exec_cmd("gnome-keyring-daemon --start --components=secrets")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("pkill xfce4-notifyd 2>/dev/null; mako")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("trash-empty 30")
    hl.exec_cmd("hyprctl setcursor Qogir-Dark 24")
    hl.exec_cmd("/usr/lib/geoclue-2.0/demos/agent")
    hl.exec_cmd("mpris-proxy")
    hl.exec_cmd("caelestia resizer -d")
    hl.exec_cmd("waybar")
    hl.exec_cmd("$HOME/.config/hypr/scripts/wallpaper-hook.fish")
    hl.exec_cmd("sleep 3 && ~/.config/waybar/auto-hide.fish")
    hl.exec_cmd("caelestia shell -d")
    hl.exec_cmd("hyprsunset --temperature 4000")
    hl.exec_cmd("$HOME/.config/hypr/scripts/eye-break.sh")
    hl.exec_cmd("$HOME/.config/waybar/scripts/prayer-daemon.sh")
end)

